$GLOBALS['gc_results']=[];
function gc_same(mixed $want,mixed $got):void{if($want!==$got)throw new RuntimeException('Expected '.json_encode($want).' got '.json_encode($got));}
function gc_true(mixed $value):void{if(!$value)throw new RuntimeException('Assertion failed');}
function gc_reject(callable $f,string $code=''):void{try{$f();}catch(Throwable $e){if($code&&!str_contains($e->getMessage(),$code))throw $e;return;}throw new RuntimeException('Rejection required');}
function gc_test(string $id,callable $fn):void{$start=hrtime(true);try{$fn();$GLOBALS['gc_results'][]=['test'=>$id,'status'=>'PASS','ms'=>intdiv(hrtime(true)-$start,1000000)];}catch(Throwable $e){$GLOBALS['gc_results'][]=['test'=>$id,'status'=>'FAIL','error'=>$e->getMessage(),'file'=>basename($e->getFile()),'line'=>$e->getLine()];}wp_set_current_user(1);update_option('gc_mode','standalone');}
function gc_product(int $stock=100,bool $virtual=true):WC_Product{
    $p=new WC_Product_Simple();$p->set_name('Integration fixture');$p->set_status('publish');$p->set_catalog_visibility('hidden');$p->set_sku('TEST-'.wp_generate_uuid4());$p->set_regular_price('10000000');$p->set_manage_stock(true);$p->set_stock_quantity($stock);$p->set_backorders('no');$p->set_virtual($virtual);$p->set_tax_status('none');
    $p->update_meta_data('_gc_product',['price_type'=>'FIXED','category'=>'new','net_weight'=>'2.5','gross_weight'=>'2.5','purity'=>'750','fixed_price'=>'25000000','making_mode'=>'fixed','making_value'=>'1000000','profit_mode'=>'percent','profit_value'=>'7','supply_status'=>'available']);$p->save();return $p;
}
function gc_order(?WC_Product $p=null):WC_Order{$p??=gc_product();$o=wc_create_order(['customer_id'=>1,'status'=>'gc-await-quote']);$o->set_billing_email('fixture@example.test');$o->set_currency('IRR');$o->add_product($p,1);$o->update_meta_data('_gc_specialized','yes');$o->save();return $o;}
function gc_issued():array{$o=gc_order();return [$o,Quotes::issue($o->get_id())];}
function gc_started():array{[$o,$q]=gc_issued();$b=Quotes::begin($q['uuid'],$q['token']);return [$o,$q,$b];}
function gc_scope(MockProvider $p,string $key):array{return ['schema_version'=>'1','store_uuid'=>$p->store,'company_id'=>$p->company,'idempotency_key'=>$key];}
function gc_reserve(MockProvider $p,string $key='reserve'):array{return gc_scope($p,$key)+['sku'=>'SKU-1','qty'=>1,'expires_at'=>time()+600,'order_uuid'=>'order-1'];}
function gc_sale(MockProvider $p,string $reservation):array{return gc_scope($p,'sale')+['reservation_id'=>$reservation,'order_uuid'=>'order-1','warehouse_id'=>'LOGICAL-1','amount_minor'=>'2807380000','scale'=>2,'currency'=>'IRR'];}
function gc_mock():MockProvider{$m=new MockProvider(wp_generate_uuid4(),'COMPANY-A');$m->seed('SKU-1',1,'2807380000');return $m;}

